function solve(a,b){if(a.length<3){throw new RangeError('At least three numbers are required');}const c=[...a].sort((a,b)=>a-b);let d=c[0]+c[1]+c[2];for(let i=0;i<c.length-2;i++){if(i>0&&c[i]===c[i-1]){continue;}let a=i+1;let e=c.length-1;while(a<e){const f=c[i]+c[a]+c[e];const g=Math.abs(f-b);const h=Math.abs(d-b);if(g<h||g===h&&f<d){d=f;}if(f===b){return f;}if(f<b){a++;}else{e--;}}}return d;}
